package sfz.batch.l14.demo

import java.time.Duration
import java.time.Instant
import kotlin.random.Random

/**
 * A month of card payments with fraud labels, and the feature "chargebacks on this card in the
 * last 30 days", computed every night. The training set is built twice: once with each card's
 * newest feature value, once point in time. Then a one-line rule, "flag the payment if the card
 * has had a chargeback", is scored on both, and on what it would really see in production.
 */
private data class Label(val card: Int, val at: Instant, val fraud: Boolean)
private data class Row(val card: Int, val asOf: Instant, val computedAt: Instant, val value: Int)

fun main() {
    val start = Instant.parse("2026-10-01T00:00:00Z")
    val rnd = Random(11)
    val labels = mutableListOf<Label>()
    val chargebacks = mutableListOf<Pair<Int, Instant>>()
    for (card in 0 until 5_000) {
        val compromisedFrom = if (rnd.nextDouble() < 0.05) 3 + rnd.nextInt(24) else Int.MAX_VALUE
        for (d in 0 until 30) {
            val at = start.plus(Duration.ofDays(d.toLong())).plusSeconds(rnd.nextLong(86_400))
            val fraud = d >= compromisedFrom && rnd.nextDouble() < 0.6
            labels += Label(card, at, fraud)
            if (fraud) chargebacks += card to at.plus(Duration.ofHours(48 + rnd.nextLong(144)))
            else if (rnd.nextDouble() < 0.003) chargebacks += card to at.plus(Duration.ofHours(120 + rnd.nextLong(360)))
        }
    }
    val byCard = chargebacks.groupBy({ it.first }, { it.second })
    val rows = (0 until 5_000).flatMap { card ->
        (0..30).map { d ->
            val asOf = start.plus(Duration.ofDays(d.toLong()))
            Row(card, asOf, asOf.plus(Duration.ofHours(2)), byCard[card].orEmpty().count { it < asOf && it >= asOf.minus(Duration.ofDays(30)) })
        }
    }
    val history = rows.groupBy { it.card }.mapValues { (_, r) -> r.sortedBy { it.asOf } }

    val newest = labels.map { l -> l to history.getValue(l.card).last() }
    val pointInTime = labels.map { l -> l to history.getValue(l.card).lastOrNull { it.asOf <= l.at && it.computedAt <= l.at } }
    println("labels: %,d payments, %,d of them fraud; feature rows: %,d".format(labels.size, labels.count { it.fraud }, rows.size))
    println("newest-row join:    %,d labels got a value computed after the payment".format(newest.count { (l, r) -> r.computedAt > l.at }))
    println("point-in-time join: %,d".format(pointInTime.count { (l, r) -> r != null && r.computedAt > l.at }))

    fun score(name: String, set: List<Pair<Label, Row?>>) {
        val flagged = set.filter { (_, r) -> (r?.value ?: 0) >= 1 }
        val caught = flagged.count { it.first.fraud }
        println("%-38s flags %,6d payments: precision %3.0f%%, recall %3.0f%%".format(name, flagged.size,
            100.0 * caught / flagged.size, 100.0 * caught / labels.count { it.fraud }))
    }
    println("the rule \"the card has had a chargeback in the last 30 days\":")
    score("  trained on the newest-row join", newest)
    score("  trained on the point-in-time join", pointInTime)
    score("  in production (what it can see live)", pointInTime)
}

package sfz.batch.l14.demo

import java.io.File
import java.nio.file.Files
import java.nio.file.StandardCopyOption
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean
import kotlin.concurrent.thread
import kotlin.random.Random

/**
 * Last night's batch job scored 1,000,000 merchants again. Two ways to get the new scores to the
 * service that reads them: write them one by one into the live store while it serves, or build a
 * new read-only file offline and switch to it in one step. A reader samples 1,000 merchants while
 * each runs.
 */
fun main() {
    val n = 1_000_000
    val keys = Array(n) { "merchant-%07d".format(it) }
    val pick = Random(1)
    val sample = (0 until 1_000).map { keys[pick.nextInt(n)] }

    // 1. row by row into the live store, in the order the job's tasks happen to finish
    val live = ConcurrentHashMap<String, String>(n * 2)
    keys.forEach { live[it] = "run-1" }
    val seen = mutableListOf<Int>()
    val writing = AtomicBoolean(true)
    val reader = thread {
        while (writing.get()) {
            seen += sample.count { live[it] == "run-2" }
            Thread.sleep(20)
        }
    }
    val t0 = System.nanoTime()
    for (i in keys.indices.shuffled(Random(2))) live[keys[i]] = "run-2"
    writing.set(false)
    reader.join()
    val inPlaceMs = (System.nanoTime() - t0) / 1e6
    val mixed = seen.filter { it in 1..999 }
    println("in place: %,d writes in %.0f ms; the reader looked %d times while it ran, and %d of those reads mixed both runs".format(
        n, inPlaceMs, seen.size, mixed.size))
    if (mixed.isNotEmpty()) println("  for example, %d of the 1,000 sampled merchants had new scores and %d still had old ones".format(mixed[mixed.size / 2], 1_000 - mixed[mixed.size / 2]))

    // 2. offline: write a sorted file in a new folder, then flip a pointer
    val root = File("build/l14/scores").apply { deleteRecursively(); mkdirs() }
    val t1 = System.nanoTime()
    val v2 = File(root, "v2").apply { mkdirs() }
    File(v2, "data").bufferedWriter().use { w -> for (k in keys.sorted()) { w.write(k); w.write("\trun-2\n") } }
    val buildMs = (System.nanoTime() - t1) / 1e6
    val tmp = File(root, "CURRENT.tmp").apply { writeText("v2") }
    val t2 = System.nanoTime()
    Files.move(tmp.toPath(), File(root, "CURRENT").toPath(), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING)
    val swapUs = (System.nanoTime() - t2) / 1e3
    println("offline: built a sorted file of %,d entries (%.1f MB) in %.0f ms, which no reader could see;".format(
        n, File(v2, "data").length() / 1e6, buildMs))
    println("  then the switch took %.0f microseconds: a reader sees run 1 or run 2, never both".format(swapUs))
}

package sfz.batch.l14.demo

import java.io.File
import java.nio.file.Files
import java.nio.file.StandardCopyOption

/**
 * Three nights of a serving store built by a batch job: a good build, a build that crashes
 * halfway, and a build with bad scores that is published and then rolled back. Prints the folder
 * and what a reader gets after each step.
 */
fun main() {
    val root = File("build/l14/store").apply { deleteRecursively(); mkdirs() }
    val current = File(root, "CURRENT")
    fun publish(v: String) {
        val tmp = File(root, "CURRENT.tmp").apply { writeText(v) }
        Files.move(tmp.toPath(), current.toPath(), StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING)
    }
    fun build(v: String, score: Int, crashAfter: Int = Int.MAX_VALUE) {
        val dir = File(root, v).apply { mkdirs() }
        File(dir, "data").bufferedWriter().use { w ->
            for (m in 0 until 1_000) {
                if (m == crashAfter) throw IllegalStateException("executor lost while writing $v")
                w.write("merchant-%04d\t$score\n".format(m))
            }
        }
    }
    fun read(): String {
        val v = current.readText()
        val line = File(root, "$v/data").readLines().first { it.startsWith("merchant-0042\t") }
        return "CURRENT=$v, merchant-0042 scores ${line.substringAfter('\t')}"
    }
    fun show(step: String) {
        val folders = root.list()!!.filter { it.startsWith("v") }.sorted().joinToString { v ->
            "$v (${File(root, "$v/data").readLines().size} lines)"
        }
        println("$step\n  folders: $folders\n  a reader: ${read()}")
    }

    build("v1", 17); publish("v1"); show("night 1: build v1, publish")
    runCatching { build("v2", 18, crashAfter = 400) }.onFailure { println("night 2: the build failed: ${it.message}") }
    show("  nothing was published")
    build("v3", 0); publish("v3"); show("night 3: build v3 with a bug (every score 0), publish")
    publish("v1"); show("rollback: publish v1 again")
}

