        val ps = c.prepareStatement("UPDATE merchant_risk SET score = ? WHERE merchant_id = ?")
        rows.forEach { r ->
            ps.setDouble(1, r.score); ps.setLong(2, r.merchantId)
            ps.executeUpdate()          // one round trip per row, visible at once
        }
