Options().use { opts ->
    SstFileWriter(EnvOptions(), opts).use { w ->
        w.open("$root/v$runId/scores.sst")
        for (row in scores.toLocalIterator()) {
            w.put(key(row.getLong(0)), value(row.getDouble(1)))   // keys must strictly increase
        }
        w.finish()
    }
}
